#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps it GC-reachable; a raw pointer was purged mid-match (log 21:05:13 GC, 21:05:27 crash).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker was a raw UArenaScoreTracker* without UPROPERTY, so the garbage collector (log 21:05:13, 412 objects purged) freed it; the next goal called AddPoints on a dangling pointer (access violation, ArenaScoreTracker.cpp:18). Fixed with UPROPERTY() TObjectPtr.",
  "no_colors_cause": "/Game/Data/Palettes/DA_Primary is loaded only by a string path in LoadObject, so cooking never sees it; it was not cooked (DirectoriesToAlwaysCook lacked Palettes), so LoadObject returned null and the HUD used fallback gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
